"""从馆藏核对快照生成本地导航页，不联网。"""
import release_runtime
import json
from pathlib import Path
root = Path(__file__).resolve().parent
snapshot = json.loads((root / '浙大资源访问方式核对.json').read_text(encoding='utf-8'))
data = json.dumps(snapshot['items'], ensure_ascii=False).replace('<', '\\u003c')
html = '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>浙大馆藏接口导航</title><style>\nbody{font:16px/1.6 -apple-system,BlinkMacSystemFont,sans-serif;color:#17283c;max-width:1100px;margin:32px auto;padding:0 20px;background:#f6f8fa} h1{margin-bottom:0} .note{color:#455b71} .controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;position:sticky;top:0;background:#f6f8fa;padding:12px 0} input[type=search]{font:inherit;padding:9px;border:1px solid #aab8c6;border-radius:6px;min-width:260px} article{background:white;border:1px solid #d9e1e8;border-radius:9px;padding:14px 18px;margin:10px 0} h2{font-size:18px;margin:0 0 3px}.meta{color:#496075;font-size:14px} a{color:#075aa0;margin-right:16px}.yes{color:#086341}.no{color:#74561b} code{font-size:14px}\n</style></head><body><h1>浙大馆藏接口导航</h1><p class="note">基于 2026-10-27 图书馆导航与介绍页快照。已验证仅指所列功能和当时会话；全文、当前机构授权及其他功能需要另行核对。资源列表不保证涵盖全部馆藏。</p><div class="controls"><input id="q" type="search" placeholder="搜索名称、编号或接口名称" aria-label="搜索馆藏"><label><input type="checkbox" id="verified"> 仅看有验证记录</label><span id="count" aria-live="polite"></span></div><main id="results"></main><script>\nconst items = DATA;\nconst q=document.getElementById(\'q\'),verified=document.getElementById(\'verified\'),results=document.getElementById(\'results\'),count=document.getElementById(\'count\');\nfunction element(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}\nfunction link(label,url){const a=element(\'a\',label);a.href=url;a.rel=\'noreferrer\';return a}\nfunction render(){const query=q.value.trim().toLowerCase();const rows=items.filter(x=>(!verified.checked||x.tested_browser_search||x.tested_cli)&&[x.name,x.id,x.tested_browser_search?.source_key,x.tested_browser_search?.scope,x.tested_cli?.command,x.tested_cli?.scope].some(y=>String(y||\'\').toLowerCase().includes(query)));count.textContent=`显示 ${rows.length} / ${items.length}`;results.replaceChildren();for(const x of rows){const a=element(\'article\',\'\');a.append(element(\'h2\',x.name));if(x.resource_classification)a.append(element(\'p\',`类型说明：${x.resource_classification.note}`,\'meta\'));a.append(element(\'div\',`编号 ${x.id} · 校内：${x.on_campus?.methods?.join(\'、\')||\'未提取\'} · 校外：${x.off_campus?.methods?.join(\'、\')||\'未提取\'}`,\'meta\'));const t=x.tested_browser_search;if(t)a.append(element(\'p\',`已验证：${t.source_key}；${t.scope}（${t.verified_on}）`,\'yes\'));else if(!x.tested_cli)a.append(element(\'p\',\'未标记已验证的业务功能\',\'no\'));if(x.tested_cli)a.append(element(\'p\',`已验证命令：${x.tested_cli.command}；${x.tested_cli.scope}（${x.tested_cli.verified_on}）`,\'yes\'));a.append(link(\'馆藏介绍\',x.info_url),link(\'资源入口\',x.visit_url));results.append(a)}}\nq.addEventListener(\'input\',render);verified.addEventListener(\'change\',render);render();\n</script></body></html>'.replace('DATA', data, 1)
(root / '馆藏导航.html').write_text(html, encoding='utf-8')
print(f"已生成 {len(snapshot['items'])} 条馆藏导航")
